import { useCallback, useEffect, useMemo, useState } from "react";

import { CommandPalette } from "./components/CommandPalette";
import { AddProjectDialog, AddWorktreeDialog } from "./components/ProjectDialogs";
import { SettingsDialog } from "./components/SettingsDialog";
import { Sidebar } from "./components/Sidebar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorktreeDeleteDialog } from "./components/WorktreeDeleteDialog";
import { useShortcuts } from "./lib/shortcuts";
import { DEFAULT_WORKSPACE_ID, getWorktreeStatus, registerProject, type RegisteredProject } from "./lib/tauri";
import { worktreeIdentity, type DirtyState, type Worktree } from "./lib/types";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

const PROJECTS_STORAGE_KEY = "rorca.projects";
const ACTIVE_PROJECT_STORAGE_KEY = "rorca.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "orca.sidebar.open";
const DEFAULT_PROJECT: RegisteredProject = { workspaceId: DEFAULT_WORKSPACE_ID, repoRoot: "." };

export function App() {
  const [projects, setProjects] = useState<RegisteredProject[]>(loadProjects);
  const [activeProjectId, setActiveProjectId] = useState(loadActiveProjectId);
  const activeProject = useMemo(
    () => projects.find((project) => project.workspaceId === activeProjectId) ?? projects[0] ?? DEFAULT_PROJECT,
    [activeProjectId, projects],
  );

  const {
    state,
    agents,
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    disableSplit,
    updateTabTitle,
    activatePrimary,
    syncWorktrees,
  } = useWorkspaceStore({ workspaceId: activeProject.workspaceId });
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    workspaceId: activeProject.workspaceId,
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });

  useEffect(() => {
    void registerProject({
      workspaceId: activeProject.workspaceId,
      repoPath: activeProject.repoRoot,
    })
      .then(() => refreshWorktrees())
      .catch(reportRuntimeError);
  }, [activeProject.repoRoot, activeProject.workspaceId, refreshWorktrees, reportRuntimeError]);

  const [isAddProjectOpen, setIsAddProjectOpen] = useState(false);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(loadSidebarOpen);
  const [deleteTarget, setDeleteTarget] = useState<Worktree | null>(null);
  const [worktreeStatuses, setWorktreeStatuses] = useState<Record<string, DirtyState | undefined>>({});

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen((current) => {
      const next = !current;
      persistSidebarOpen(next);
      return next;
    });
  }, []);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );

  const handleSelectProject = useCallback(
    (project: RegisteredProject) => {
      if (project.workspaceId === activeProject.workspaceId) return;
      setActiveProjectId(project.workspaceId);
      persistActiveProjectId(project.workspaceId);
      setWorktreeStatuses({});
      setDeleteTarget(null);
    },
    [activeProject.workspaceId],
  );

  const handleRegisteredProject = useCallback((project: RegisteredProject) => {
    setProjects((current) => {
      const next = [...current.filter((candidate) => candidate.workspaceId !== project.workspaceId), project];
      persistProjects(next);
      return next;
    });
    setActiveProjectId(project.workspaceId);
    persistActiveProjectId(project.workspaceId);
    setWorktreeStatuses({});
  }, []);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      // A worktree selected from another project's tree must switch the active project first,
      // because the workspace store only ever holds the active project's worktrees.
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId ? projects.find((project) => project.workspaceId === ownerId) : undefined;
      if (owner && owner.workspaceId !== activeProject.workspaceId) {
        handleSelectProject(owner);
        return;
      }
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [activeProject.workspaceId, ensureTabForWorktree, handleSelectProject, projects, reportRuntimeError],
  );

  const handleSelectTerminalTab = useCallback(
    (tabId: string) => {
      const tab = state.layout.tabs.find((candidate) => candidate.id === tabId);
      const session = tab ? state.sessions[tab.sessionId] : undefined;
      const worktree = session ? state.worktrees.find((candidate) => candidate.path === session.cwd) : undefined;
      if (!worktree || worktree.path === state.activeWorktreePath) {
        activatePrimary(tabId);
        return;
      }
      void ensureTabForWorktree(worktree)
        .then(() => activatePrimary(tabId))
        .catch(reportRuntimeError);
    },
    [activatePrimary, ensureTabForWorktree, reportRuntimeError, state.activeWorktreePath, state.layout.tabs, state.sessions, state.worktrees],
  );

  const handleRefreshWorktreeStatus = useCallback(
    (worktree: Worktree) => {
      const identity = worktreeIdentity(worktree);
      if (!identity) return;
      void getWorktreeStatus({ workspaceId: activeProject.workspaceId, worktree: identity })
        .then((status) => {
          setWorktreeStatuses((current) => ({ ...current, [worktree.path]: status }));
        })
        .catch(reportRuntimeError);
    },
    [activeProject.workspaceId, reportRuntimeError],
  );

  const handleAddTerminalTab = useCallback(() => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  }, [activeWorktree, openTab, reportRuntimeError]);

  const handleCloseTab = useCallback(
    (tabId: string) => {
      void closeTab(tabId).catch(reportRuntimeError);
    },
    [closeTab, reportRuntimeError],
  );

  const handleCycleTab = useCallback(
    (offset: number) => {
      const tabs = state.layout.tabs;
      if (tabs.length < 2) return;
      const currentIndex = Math.max(0, tabs.findIndex((tab) => tab.id === state.layout.primaryTabId));
      const nextIndex = (currentIndex + offset + tabs.length) % tabs.length;
      handleSelectTerminalTab(tabs[nextIndex].id);
    },
    [handleSelectTerminalTab, state.layout.primaryTabId, state.layout.tabs],
  );

  const splitRight = useCallback(() => {
    void enableSplit("horizontal").catch(reportRuntimeError);
  }, [enableSplit, reportRuntimeError]);
  const splitDown = useCallback(() => {
    void enableSplit("vertical").catch(reportRuntimeError);
  }, [enableSplit, reportRuntimeError]);

  const handleSelectWorktreeByIndex = useCallback(
    (index: number) => {
      const target = state.worktrees[index];
      if (target) {
        handleSelectWorktree(target);
      }
    },
    [handleSelectWorktree, state.worktrees],
  );

  const handleSelectTerminalTabByIndex = useCallback(
    (index: number) => {
      const target = state.layout.tabs[index];
      if (target) {
        handleSelectTerminalTab(target.id);
      }
    },
    [handleSelectTerminalTab, state.layout.tabs],
  );

  const shortcutHandlers = useMemo(
    () => ({
      "tab.newTerminal": handleAddTerminalTab,
      "tab.close": () => {
        if (state.layout.primaryTabId) handleCloseTab(state.layout.primaryTabId);
      },
      "tab.next": () => handleCycleTab(1),
      "tab.previous": () => handleCycleTab(-1),
      "tab.select1": () => handleSelectTerminalTabByIndex(0),
      "tab.select2": () => handleSelectTerminalTabByIndex(1),
      "tab.select3": () => handleSelectTerminalTabByIndex(2),
      "tab.select4": () => handleSelectTerminalTabByIndex(3),
      "workspace.select1": () => handleSelectWorktreeByIndex(0),
      "workspace.select2": () => handleSelectWorktreeByIndex(1),
      "workspace.select3": () => handleSelectWorktreeByIndex(2),
      "workspace.select4": () => handleSelectWorktreeByIndex(3),
      "terminal.splitRight": splitRight,
      "terminal.splitDown": splitDown,
      "terminal.unsplit": disableSplit,
      "sidebar.left.toggle": toggleSidebar,
      "commandPalette.open": () => setIsCommandPaletteOpen(true),
    }),
    [
      disableSplit,
      handleAddTerminalTab,
      handleCloseTab,
      handleCycleTab,
      handleSelectTerminalTabByIndex,
      handleSelectWorktreeByIndex,
      splitDown,
      splitRight,
      state.layout.primaryTabId,
      toggleSidebar,
    ],
  );
  useShortcuts(shortcutHandlers);

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      <Sidebar
        open={isSidebarOpen}
        projects={projects}
        activeProjectId={activeProject.workspaceId}
        worktrees={state.worktrees}
        agents={agents}
        activePath={activeWorktree?.path || ""}
        statuses={worktreeStatuses}
        onSelectProject={handleSelectProject}
        onAddProject={() => setIsAddProjectOpen(true)}
        onSelectWorktree={handleSelectWorktree}
        onCreateWorktree={() => setIsCreateOpen(true)}
        onRefreshWorktreeStatus={handleRefreshWorktreeStatus}
        onDeleteWorktree={setDeleteTarget}
        onOpenCommandPalette={() => setIsCommandPaletteOpen(true)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        onToggle={toggleSidebar}
      />

      <main className="flex h-full min-w-0 flex-1 flex-col overflow-hidden bg-background">
        {activeWorktree ? (
          <TerminalSplitView
            layout={state.layout}
            sessions={state.sessions}
            onActivateTab={handleSelectTerminalTab}
            onCloseTab={handleCloseTab}
            onAddTab={handleAddTerminalTab}
            onSplitRight={splitRight}
            onSplitDown={splitDown}
            onUnsplit={disableSplit}
            onTitleChange={updateTabTitle}
          />
        ) : (
          <div className="flex h-full flex-1 items-center justify-center bg-[#23262d] text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      <CommandPalette
        open={isCommandPaletteOpen}
        worktrees={state.worktrees}
        tabs={state.layout.tabs}
        onSelectWorktree={handleSelectWorktree}
        onSelectTab={handleSelectTerminalTab}
        onClose={() => setIsCommandPaletteOpen(false)}
      />
      <SettingsDialog open={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} />
      {isAddProjectOpen ? (
        <AddProjectDialog onClose={() => setIsAddProjectOpen(false)} onRegistered={handleRegisteredProject} />
      ) : null}
      {isCreateOpen ? (
        <AddWorktreeDialog
          project={activeProject}
          onClose={() => setIsCreateOpen(false)}
          onCreated={async (worktree) => {
            await refreshWorktrees();
            await ensureTabForWorktree(worktree).catch(reportRuntimeError);
          }}
        />
      ) : null}
      {deleteTarget ? (
        <WorktreeDeleteDialog
          workspaceId={activeProject.workspaceId}
          worktree={deleteTarget}
          onClose={() => setDeleteTarget(null)}
          onDeleted={() => {
            setWorktreeStatuses((current) => {
              const next = { ...current };
              delete next[deleteTarget.path];
              return next;
            });
            void refreshWorktrees();
          }}
        />
      ) : null}

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}
    </div>
  );
}

function loadProjects(): RegisteredProject[] {
  try {
    const raw = window.localStorage.getItem(PROJECTS_STORAGE_KEY);
    if (!raw) return [DEFAULT_PROJECT];
    const parsed = JSON.parse(raw) as RegisteredProject[];
    if (!Array.isArray(parsed)) return [DEFAULT_PROJECT];
    const valid = parsed.filter(
      (project) => project && typeof project.workspaceId === "string" && typeof project.repoRoot === "string",
    );
    return valid.length > 0 ? valid : [DEFAULT_PROJECT];
  } catch {
    return [DEFAULT_PROJECT];
  }
}

function persistProjects(projects: RegisteredProject[]) {
  try {
    window.localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(projects));
  } catch {
    // A local persistence failure must not block native project registration.
  }
}

function loadActiveProjectId() {
  try {
    return window.localStorage.getItem(ACTIVE_PROJECT_STORAGE_KEY) || DEFAULT_WORKSPACE_ID;
  } catch {
    return DEFAULT_WORKSPACE_ID;
  }
}

function persistActiveProjectId(workspaceId: string) {
  try {
    window.localStorage.setItem(ACTIVE_PROJECT_STORAGE_KEY, workspaceId);
  } catch {
    // The selected project still remains active for this session.
  }
}

function loadSidebarOpen() {
  try {
    const raw = window.localStorage.getItem(SIDEBAR_OPEN_STORAGE_KEY);
    return raw !== null ? raw !== "false" : true;
  } catch {
    return true;
  }
}

function persistSidebarOpen(open: boolean) {
  try {
    window.localStorage.setItem(SIDEBAR_OPEN_STORAGE_KEY, String(open));
  } catch {
    // Persistence failure should not break in-memory state.
  }
}

export default App;

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const native = vi.hoisted(() => ({
  createWorktree: vi.fn(),
  getWorktreeStatus: vi.fn(),
  listProjectBranches: vi.fn(),
  registerProject: vi.fn(),
  signalTerminal: vi.fn(),
}));

const workspace = vi.hoisted(() => ({
  activatePrimary: vi.fn(),
  closeTab: vi.fn(),
  disableSplit: vi.fn(),
  enableSplit: vi.fn(),
  ensureTabForWorktree: vi.fn().mockResolvedValue(undefined),
  openTab: vi.fn(),
  refreshWorktrees: vi.fn(),
  rotateSplit: vi.fn(),
  syncWorktrees: vi.fn(),
  storeState: {
    activeWorktreePath: "/repo/main",
    layout: {
      primaryTabId: "tab-1",
      secondaryTabId: null,
      split: "none" as const,
      tabs: [
        { id: "tab-1", label: "main", sessionId: "sess-1" },
        { id: "tab-2", label: "feature", sessionId: "sess-2" },
        { id: "tab-3", label: "bugfix", sessionId: "sess-3" },
        { id: "tab-4", label: "docs", sessionId: "sess-4" },
      ],
    },
    sessions: {
      "sess-1": { id: "sess-1", cwd: "/repo/main" },
      "sess-2": { id: "sess-2", cwd: "/repo/feature" },
      "sess-3": { id: "sess-3", cwd: "/repo/bugfix" },
      "sess-4": { id: "sess-4", cwd: "/repo/docs" },
    },
    worktrees: [
      { path: "/repo/main", branch: "refs/heads/main" },
      { path: "/repo/feature", branch: "refs/heads/feature" },
      { path: "/repo/bugfix", branch: "refs/heads/bugfix" },
      { path: "/repo/docs", branch: "refs/heads/docs" },
    ],
  },
}));

vi.mock("./lib/tauri", () => ({
  DEFAULT_WORKSPACE_ID: "default",
  createWorktree: native.createWorktree,
  getWorktreeStatus: native.getWorktreeStatus,
  listProjectBranches: native.listProjectBranches,
  registerProject: native.registerProject,
  signalTerminal: native.signalTerminal,
  toIpcError: (error: unknown) => error,
}));

vi.mock("./state/workspaceStore", () => ({
  useWorkspaceStore: () => ({
    state: workspace.storeState,
    agents: [],
    activatePrimary: workspace.activatePrimary,
    closeTab: workspace.closeTab,
    disableSplit: workspace.disableSplit,
    enableSplit: workspace.enableSplit,
    ensureTabForWorktree: workspace.ensureTabForWorktree,
    openTab: workspace.openTab,
    rotateSplit: workspace.rotateSplit,
    syncWorktrees: workspace.syncWorktrees,
  }),
}));

vi.mock("./state/workspaceRuntime", () => ({
  useWorkspaceRuntime: () => ({
    refreshWorktrees: workspace.refreshWorktrees,
    reportRuntimeError: vi.fn(),
    runtimeError: null,
  }),
}));

vi.mock("./components/Sidebar", () => ({
  Sidebar: ({
    open = true,
    onAddProject,
    onCreateWorktree,
    onSelectProject,
    onSelectWorktree,
    onToggle,
    projects = [],
    worktrees = [],
    activeProjectId,
  }: {
    open?: boolean;
    onAddProject?: () => void;
    onCreateWorktree: () => void;
    onSelectProject?: (project: { workspaceId: string }) => void;
    onSelectWorktree?: (worktree: { path: string }) => void;
    onToggle?: () => void;
    projects?: Array<{ workspaceId: string }>;
    worktrees?: Array<{ path: string }>;
    activeProjectId?: string;
  }) => (
    <div data-testid="mock-sidebar" data-open={open}>
      <button type="button" onClick={onToggle}>
        {open ? "Hide sidebar" : "Show sidebar"}
      </button>
      {open ? (
        <>
          <button type="button" onClick={() => onAddProject?.()}>
            Add project
          </button>
          <button type="button" onClick={onCreateWorktree}>
            Add worktree
          </button>
          <span>Active project {activeProjectId}</span>
          {/* Mirrors the real nested tree: every project row, with the active project's worktrees under it. */}
          {projects.map((project) => (
            <div key={project.workspaceId}>
              <button type="button" onClick={() => onSelectProject?.(project)}>
                Project {project.workspaceId}
              </button>
              {project.workspaceId === activeProjectId
                ? worktrees.map((worktree) => (
                    <button key={worktree.path} type="button" onClick={() => onSelectWorktree?.(worktree)}>
                      Worktree {worktree.path}
                    </button>
                  ))
                : null}
            </div>
          ))}
        </>
      ) : null}
    </div>
  ),
}));

vi.mock("./components/CommandPalette", () => ({ CommandPalette: () => null }));
vi.mock("./components/SettingsDialog", () => ({ SettingsDialog: () => null }));
vi.mock("./components/TerminalSplitView", () => ({ TerminalSplitView: () => null }));
vi.mock("./components/WorktreeDeleteDialog", () => ({ WorktreeDeleteDialog: () => null }));

import { App } from "./App";

afterEach(cleanup);

describe("App project workspace flow", () => {
  beforeEach(() => {
    localStorage.clear();
    native.createWorktree.mockReset();
    native.getWorktreeStatus.mockReset();
    native.listProjectBranches.mockReset();
    native.registerProject.mockReset();
    native.signalTerminal.mockReset();
    workspace.activatePrimary.mockReset();
    workspace.ensureTabForWorktree.mockReset();
    workspace.ensureTabForWorktree.mockResolvedValue(undefined);
    workspace.refreshWorktrees.mockReset();
  });

  it("re-registers the active persisted project before refreshing its worktrees", async () => {
    const project = { workspaceId: "rorca", repoRoot: "/repos/rorca" };
    localStorage.setItem("rorca.projects", JSON.stringify([project]));
    localStorage.setItem("rorca.active-project", project.workspaceId);
    native.registerProject.mockResolvedValue(project);

    render(<App />);

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: project.workspaceId,
        repoPath: project.repoRoot,
      }),
    );
    await waitFor(() => expect(workspace.refreshWorktrees).toHaveBeenCalledOnce());
  });

  it("opens a registered project's real branch-dropdown worktree flow", async () => {
    native.registerProject.mockResolvedValue({ workspaceId: "rorca", repoRoot: "/repos/rorca" });
    native.listProjectBranches.mockResolvedValue([{ name: "main", isCurrent: true }]);

    render(<App />);

    fireEvent.click(screen.getByRole("button", { name: "Add project" }));
    expect(screen.getByRole("form", { name: "Add Project" })).toBeInTheDocument();
    fireEvent.change(screen.getByRole("textbox", { name: "Workspace id" }), { target: { value: "rorca" } });
    fireEvent.change(screen.getByRole("textbox", { name: "Repository path" }), { target: { value: "/repos/rorca" } });
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() => expect(screen.getByText("Project rorca")).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "Add worktree" }));

    expect(screen.getByRole("form", { name: "Add Worktree" })).toBeInTheDocument();
    await waitFor(() => expect(native.listProjectBranches).toHaveBeenCalledWith("rorca"));
    expect(screen.getByRole("combobox", { name: "Base branch" })).toBeInTheDocument();
  });

  it("switches the active project when selecting a project row in the nested tree", async () => {
    const projects = [
      { workspaceId: "alpha", repoRoot: "/repos/alpha" },
      { workspaceId: "beta", repoRoot: "/repos/beta" },
    ];
    localStorage.setItem("rorca.projects", JSON.stringify(projects));
    localStorage.setItem("rorca.active-project", "alpha");
    native.registerProject.mockImplementation(async ({ workspaceId }: { workspaceId: string }) => ({
      workspaceId,
      repoRoot: `/repos/${workspaceId}`,
    }));

    render(<App />);

    expect(screen.getByText("Active project alpha")).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "Project beta" }));

    await waitFor(() => expect(screen.getByText("Active project beta")).toBeInTheDocument());
    expect(localStorage.getItem("rorca.active-project")).toBe("beta");
    // Switching projects re-registers the newly selected project so its worktrees load.
    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({ workspaceId: "beta", repoPath: "/repos/beta" }),
    );
  });

  it("switches project instead of activating when the worktree belongs to another project", async () => {
    const projects = [
      { workspaceId: "alpha", repoRoot: "/repos/alpha" },
      { workspaceId: "beta", repoRoot: "/repos/beta" },
    ];
    localStorage.setItem("rorca.projects", JSON.stringify(projects));
    localStorage.setItem("rorca.active-project", "alpha");
    native.registerProject.mockImplementation(async ({ workspaceId }: { workspaceId: string }) => ({
      workspaceId,
      repoRoot: `/repos/${workspaceId}`,
    }));

    // A worktree owned by "beta" surfaced while "alpha" is active.
    workspace.storeState.worktrees.push({ path: "/repo/beta-feature", branch: "refs/heads/orca/beta/feature" });

    try {
      render(<App />);

      fireEvent.click(screen.getByRole("button", { name: "Worktree /repo/beta-feature" }));

      await waitFor(() => expect(screen.getByText("Active project beta")).toBeInTheDocument());
      // The worktree is not activated against the wrong project's workspace scope.
      expect(workspace.ensureTabForWorktree).not.toHaveBeenCalled();
    } finally {
      workspace.storeState.worktrees.pop();
    }
  });

  it("activates a worktree directly when it belongs to the active project", async () => {
    const project = { workspaceId: "alpha", repoRoot: "/repos/alpha" };
    localStorage.setItem("rorca.projects", JSON.stringify([project]));
    localStorage.setItem("rorca.active-project", "alpha");
    native.registerProject.mockResolvedValue(project);

    render(<App />);

    fireEvent.click(screen.getByRole("button", { name: "Worktree /repo/feature" }));

    await waitFor(() =>
      expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[1]),
    );
  });

  it("navigates workspaces with Cmd+1..4 and terminal tabs with Ctrl+1..4 ignoring out-of-range keys", async () => {
    native.registerProject.mockResolvedValue({ workspaceId: "default", repoRoot: "." });
    render(<App />);

    // Cmd+1..4 selects workspace indexes 1..4 (worktrees 0..3)
    fireEvent.keyDown(window, { key: "1", metaKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[0]);

    fireEvent.keyDown(window, { key: "2", metaKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[1]);

    fireEvent.keyDown(window, { key: "3", metaKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[2]);

    fireEvent.keyDown(window, { key: "4", metaKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[3]);

    // Ctrl+1..4 selects terminal tab indexes 1..4
    workspace.activatePrimary.mockClear();
    workspace.ensureTabForWorktree.mockClear();

    // Tab 1 is currently active worktree ("/repo/main"), so it directly activates primary tab
    fireEvent.keyDown(window, { key: "1", ctrlKey: true });
    expect(workspace.activatePrimary).toHaveBeenCalledWith("tab-1");

    // Tab 2 has cwd "/repo/feature", so handleSelectTerminalTab ensures tab for worktree and activates
    fireEvent.keyDown(window, { key: "2", ctrlKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[1]);

    fireEvent.keyDown(window, { key: "3", ctrlKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[2]);

    fireEvent.keyDown(window, { key: "4", ctrlKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[3]);

    // Out of range (index 5) or unmodified number typing is harmless
    workspace.activatePrimary.mockClear();
    workspace.ensureTabForWorktree.mockClear();

    fireEvent.keyDown(window, { key: "5", metaKey: true });
    fireEvent.keyDown(window, { key: "5", ctrlKey: true });
    fireEvent.keyDown(window, { key: "1" });
    fireEvent.keyDown(window, { key: "2" });

    expect(workspace.activatePrimary).not.toHaveBeenCalled();
    expect(workspace.ensureTabForWorktree).not.toHaveBeenCalled();
  });

  it("toggles sidebar visibility with Cmd+B and persists state across mounts", async () => {
    native.registerProject.mockResolvedValue({ workspaceId: "default", repoRoot: "." });
    const { unmount } = render(<App />);

    expect(screen.getByTestId("mock-sidebar")).toHaveAttribute("data-open", "true");
    expect(screen.getByRole("button", { name: "Hide sidebar" })).toBeInTheDocument();

    // Toggle off via Cmd+B shortcut
    fireEvent.keyDown(window, { key: "b", metaKey: true });
    expect(screen.getByTestId("mock-sidebar")).toHaveAttribute("data-open", "false");
    expect(screen.getByRole("button", { name: "Show sidebar" })).toBeInTheDocument();
    expect(localStorage.getItem("orca.sidebar.open")).toBe("false");

    // Toggle on via Show sidebar button in sidebar
    fireEvent.click(screen.getByRole("button", { name: "Show sidebar" }));
    expect(screen.getByTestId("mock-sidebar")).toHaveAttribute("data-open", "true");
    expect(localStorage.getItem("orca.sidebar.open")).toBe("true");

    // Toggle off via Hide sidebar button in sidebar
    fireEvent.click(screen.getByRole("button", { name: "Hide sidebar" }));
    expect(screen.getByTestId("mock-sidebar")).toHaveAttribute("data-open", "false");
    expect(localStorage.getItem("orca.sidebar.open")).toBe("false");

    unmount();

    // Rerender loads persisted false state
    render(<App />);
    expect(screen.getByTestId("mock-sidebar")).toHaveAttribute("data-open", "false");
    expect(screen.getByRole("button", { name: "Show sidebar" })).toBeInTheDocument();
  });
});

