import { useEffect } from "react";

export type ShortcutActionId =
  | "tab.newTerminal"
  | "tab.close"
  | "tab.next"
  | "tab.previous"
  | "tab.select1"
  | "tab.select2"
  | "tab.select3"
  | "tab.select4"
  | "workspace.select1"
  | "workspace.select2"
  | "workspace.select3"
  | "workspace.select4"
  | "terminal.splitRight"
  | "terminal.splitDown"
  | "terminal.unsplit"
  | "sidebar.left.toggle"
  | "commandPalette.open";

type ShortcutBinding = {
  key: string;
  mod?: boolean;
  control?: boolean;
  alt?: boolean;
  shift?: boolean;
};

export type ShortcutDefinition = {
  id: ShortcutActionId;
  title: string;
  group: "Tabs" | "Terminal Panes" | "Global" | "Workspaces";
  binding: ShortcutBinding;
  source: "original" | "orca-lite";
};

export const SHORTCUTS: readonly ShortcutDefinition[] = [
  {
    id: "tab.newTerminal",
    title: "New terminal tab",
    group: "Tabs",
    binding: { key: "t", mod: true },
    source: "original",
  },
  {
    id: "tab.close",
    title: "Close active tab",
    group: "Tabs",
    binding: { key: "w", mod: true },
    source: "original",
  },
  {
    id: "tab.next",
    title: "Next terminal tab",
    group: "Tabs",
    binding: { key: "PageDown", control: true },
    source: "original",
  },
  {
    id: "tab.previous",
    title: "Previous terminal tab",
    group: "Tabs",
    binding: { key: "PageUp", control: true },
    source: "original",
  },
  {
    id: "tab.select1",
    title: "Select terminal tab 1",
    group: "Tabs",
    binding: { key: "1", control: true },
    source: "orca-lite",
  },
  {
    id: "tab.select2",
    title: "Select terminal tab 2",
    group: "Tabs",
    binding: { key: "2", control: true },
    source: "orca-lite",
  },
  {
    id: "tab.select3",
    title: "Select terminal tab 3",
    group: "Tabs",
    binding: { key: "3", control: true },
    source: "orca-lite",
  },
  {
    id: "tab.select4",
    title: "Select terminal tab 4",
    group: "Tabs",
    binding: { key: "4", control: true },
    source: "orca-lite",
  },
  {
    id: "workspace.select1",
    title: "Select workspace 1",
    group: "Workspaces",
    binding: { key: "1", mod: true },
    source: "orca-lite",
  },
  {
    id: "workspace.select2",
    title: "Select workspace 2",
    group: "Workspaces",
    binding: { key: "2", mod: true },
    source: "orca-lite",
  },
  {
    id: "workspace.select3",
    title: "Select workspace 3",
    group: "Workspaces",
    binding: { key: "3", mod: true },
    source: "orca-lite",
  },
  {
    id: "workspace.select4",
    title: "Select workspace 4",
    group: "Workspaces",
    binding: { key: "4", mod: true },
    source: "orca-lite",
  },
  {
    id: "terminal.splitRight",
    title: "Split terminal right",
    group: "Terminal Panes",
    binding: { key: "d", mod: true },
    source: "original",
  },
  {
    id: "terminal.splitDown",
    title: "Split terminal down",
    group: "Terminal Panes",
    binding: { key: "d", mod: true, shift: true },
    source: "original",
  },
  {
    id: "terminal.unsplit",
    title: "Close split view",
    group: "Terminal Panes",
    binding: { key: "d", mod: true, alt: true },
    source: "orca-lite",
  },
  {
    id: "sidebar.left.toggle",
    title: "Toggle sidebar",
    group: "Global",
    binding: { key: "b", mod: true },
    source: "original",
  },
  {
    id: "commandPalette.open",
    title: "Open command palette",
    group: "Global",
    binding: { key: "k", mod: true },
    source: "orca-lite",
  },
] as const;

const SHORTCUT_BY_ID = new Map<ShortcutActionId, ShortcutDefinition>(SHORTCUTS.map((shortcut) => [shortcut.id, shortcut]));

export function shortcutLabel(id: ShortcutActionId, isMac = detectMacPlatform()) {
  const shortcut = SHORTCUT_BY_ID.get(id);
  if (!shortcut) return "";
  const binding = shortcut.binding;
  const key = displayKey(binding.key);

  if (isMac) {
    return `${binding.mod ? "⌘" : ""}${binding.control ? "⌃" : ""}${binding.alt ? "⌥" : ""}${binding.shift ? "⇧" : ""}${key}`;
  }

  return [
    binding.mod || binding.control ? "Ctrl" : null,
    binding.alt ? "Alt" : null,
    binding.shift ? "Shift" : null,
    key,
  ]
    .filter(Boolean)
    .join("+");
}

export function useShortcuts(
  handlers: Partial<Record<ShortcutActionId, () => void>>,
  options: { isMac?: boolean } = {},
) {
  const isMac = options.isMac ?? detectMacPlatform();

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      for (const shortcut of SHORTCUTS) {
        const handler = handlers[shortcut.id];
        if (!handler || !matchesBinding(event, shortcut.binding, isMac)) continue;
        if (isEditableTarget(event.target) && !isTerminalTarget(event.target) && shortcut.id !== "commandPalette.open") continue;
        event.preventDefault();
        handler();
        return;
      }
    };

    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [handlers, isMac]);
}

export function isMacShortcutPlatform() {
  return detectMacPlatform();
}

function matchesBinding(event: KeyboardEvent, binding: ShortcutBinding, isMac: boolean) {
  const expectedMeta = Boolean(binding.mod && isMac);
  const expectedControl = Boolean(binding.control || (binding.mod && !isMac));
  const matchesKey =
    (binding.key.length === 1 && (event.code === `Key${binding.key.toUpperCase()}` || event.code === `Digit${binding.key}`)) ||
    normalizeKey(event.key) === normalizeKey(binding.key);

  return (
    matchesKey &&
    event.metaKey === expectedMeta &&
    event.ctrlKey === expectedControl &&
    event.altKey === Boolean(binding.alt) &&
    event.shiftKey === Boolean(binding.shift)
  );
}

function isEditableTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) return false;
  return target.isContentEditable || target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.tagName === "SELECT";
}

function isTerminalTarget(target: EventTarget | null) {
  return target instanceof HTMLElement && target.closest(".terminal-host") !== null;
}

function normalizeKey(key: string) {
  return key.length === 1 ? key.toLowerCase() : key;
}

function displayKey(key: string) {
  if (key === "PageDown") return "PgDn";
  if (key === "PageUp") return "PgUp";
  return key.length === 1 ? key.toUpperCase() : key;
}

function detectMacPlatform() {
  if (typeof navigator === "undefined") return false;
  if (/Mac|iPhone|iPad|iPod/.test(navigator.platform)) return true;
  if (typeof navigator.userAgent === "string" && /Macintosh|Mac OS X/.test(navigator.userAgent)) return true;
  if (typeof process !== "undefined" && process.platform === "darwin") return true;
  return false;
}

import {
  ChevronRight,
  FolderGit2,
  FolderPlus,
  LayoutDashboard,
  PanelLeft,
  PanelLeftClose,
  Plus,
  Search,
  Settings2,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { cn } from "../lib/cn";
import { isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";
import type { RegisteredProject } from "../lib/tauri";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { WorktreeList } from "./WorktreeList";

export const SIDEBAR_WIDTH_STORAGE_KEY = "orca.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "rorca.sidebar.collapsedProjects";
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  open?: boolean;
  isMac?: boolean;
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: () => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette: () => void;
  onOpenSettings?: () => void;
  onToggle?: () => void;
  onHide?: () => void;
};

export function Sidebar({
  open = true,
  isMac = isMacShortcutPlatform(),
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenCommandPalette,
  onOpenSettings,
  onToggle,
  onHide,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  // Accordion state is stored as the set of *collapsed* projects, so each project keeps its own
  // open/closed state and toggling one never disturbs another. Projects the user has never
  // toggled default to collapsed unless they are the active project.
  const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(() => {
    const stored = loadCollapsedProjects();
    // Once the user has toggled anything the persisted set is authoritative; only a first run
    // (nothing persisted) falls back to "everything but the active project starts collapsed".
    return stored ?? seedCollapsedProjects(new Set<string>(), projects, activeProjectId);
  });
  const knownProjectsRef = useRef<Set<string>>(new Set(projects.map((project) => project.workspaceId)));

  useEffect(() => {
    // Projects registered after mount inherit the same default as the initial seed.
    const unseen = projects.filter((project) => !knownProjectsRef.current.has(project.workspaceId));
    if (unseen.length === 0) return;
    for (const project of unseen) knownProjectsRef.current.add(project.workspaceId);
    setCollapsedProjects((current) => seedCollapsedProjects(current, unseen, activeProjectId));
  }, [activeProjectId, projects]);

  const toggleProject = useCallback((workspaceId: string) => {
    setCollapsedProjects((current) => {
      const next = new Set(current);
      if (next.has(workspaceId)) next.delete(workspaceId);
      else next.add(workspaceId);
      persistCollapsedProjects(next);
      return next;
    });
  }, []);

  const worktreesByProject = useMemo(
    () => groupWorktreesByProject(worktrees, projects, activeProjectId),
    [activeProjectId, projects, worktrees],
  );

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const focusWorktrees = () => {
    worktreeRegionRef.current?.focus();
    worktreeRegionRef.current?.scrollIntoView?.({ block: "start" });
  };

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  if (!open) {
    const collapsedWidth = isMac ? 108 : 36;
    return (
      <aside
        className="relative flex h-full shrink-0 flex-col overflow-hidden border-r border-worktree-sidebar-border bg-worktree-sidebar text-worktree-sidebar-foreground"
        style={{ width: `${collapsedWidth}px` }}
      >
        <div
          data-testid="sidebar-drag-region"
          data-tauri-drag-region
          className="drag-region flex h-titlebar shrink-0 items-center px-2"
        >
          {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : null}
          <IconButton
            label="Show sidebar"
            className="no-drag"
            size="sm"
            onClick={onToggle}
          >
            <PanelLeft className="size-3.5" />
          </IconButton>
        </div>
        <div className="flex-1" />
      </aside>
    );
  }

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center px-2"
      >
        {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : null}
        <IconButton
          label="Hide sidebar"
          className="no-drag"
          size="sm"
          onClick={onToggle ?? onHide}
        >
          <PanelLeftClose className="size-3.5" />
        </IconButton>
      </div>

      <div className="space-y-1 px-2 pb-1">
        <button
          type="button"
          onClick={focusWorktrees}
          className="flex h-7 w-full items-center gap-2 rounded-md bg-worktree-sidebar-accent px-2 text-left text-[13px] font-medium tracking-tight text-worktree-sidebar-accent-foreground"
        >
          <LayoutDashboard className="size-3.5" />
          <span className="flex-1">Workspace</span>
        </button>
        <button
          type="button"
          onClick={onOpenCommandPalette}
          className="group relative flex h-7 w-full items-center rounded-md border border-worktree-sidebar-border/70 bg-worktree-sidebar-foreground/5 pl-7 pr-1.5 text-left text-[12px] font-medium tracking-tight text-worktree-sidebar-foreground/45 transition-colors hover:border-worktree-sidebar-border hover:bg-worktree-sidebar-foreground/8"
        >
          <Search className="pointer-events-none absolute left-2 top-1/2 size-3 -translate-y-1/2 text-worktree-sidebar-foreground/30" />
          Search workspaces
          <kbd className="ml-auto rounded border border-worktree-sidebar-border/80 bg-worktree-sidebar-foreground/8 px-1 py-px text-[9px] text-worktree-sidebar-foreground/55">
            {shortcutLabel("commandPalette.open")}
          </kbd>
        </button>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <SectionHeader
