describe("shortcut registry", () => {
  it("contains the required frontend actions with platform-aware Mod labels", () => {
    expect(SHORTCUTS.map((shortcut) => shortcut.id)).toEqual([
      "tab.newTerminal",
      "tab.close",
      "tab.next",
      "tab.previous",
      "tab.select1",
