      "terminal.unsplit",
      "sidebar.left.toggle",
      "commandPalette.open",
    ]);
    expect(shortcutLabel("tab.newTerminal", true)).toBe("⌘T");
    expect(shortcutLabel("tab.newTerminal", false)).toBe("Ctrl+T");
    expect(shortcutLabel("sidebar.left.toggle", true)).toBe("⌘B");
