    for (const project of projects) {
      if (project.workspaceId !== activeProjectId && !stored?.has(project.workspaceId) && !stored) {
        collapsed.add(project.workspaceId);
      }
    }
    return collapsed;
  } catch {
    return new Set<string>();
  }
}

